// Non-metric multidimensional scaling using Kruskal Stress-1 and R's fixed pair order.
import { cmdscale } from "./cmdscale.js";
import type { DistResult } from "./dist.js";
// Generated by `node scripts/option-keys.mjs --write` from the option types; do not edit (begin)
import { checkOptions } from "../internal/checkOptions.js";
const ISO_MDS_KEYS = ["k", "y", "maxit", "tol", "p"] as const;
// Generated by `node scripts/option-keys.mjs --write` (end)

/** Options for Kruskal non-metric multidimensional scaling. Equivalent to R's MASS::isoMDS().
 * @category Multivariate analysis
 */
export interface IsoMDSOptions {
  /** Number of output dimensions. */
  k?: number;
  /** Initial configuration with one row per object and k columns. */
  y?: readonly (readonly number[])[];
  /** Maximum number of reported iterations. */
  maxit?: number;
  /** Relative stress-change tolerance for stopping. */
  tol?: number;
  /** Minkowski power used to measure distances between configuration points. */
  p?: number;
}
/** One recorded isoMDS stress value.
 * @category Multivariate analysis
 */
export interface IsoMDSTrace {
  /** Reported iteration number. */
  iteration: number;
  /** Kruskal Stress-1, expressed as a percentage. */
  stress: number;
  /** Whether the stopping condition has been met. */
  converged: boolean;
}
/** A labelled coordinate matrix from isoMDS.
 * @category Multivariate analysis
 */
export interface IsoMDSMatrix {
  /** Object labels, or null when unnamed. */
  rows: string[] | null;
  /** Coordinate labels, or null when unnamed. */
  cols: string[] | null;
  /** Object coordinates. */
  values: number[][];
}
/** Result of non-metric multidimensional scaling.
 * @category Multivariate analysis
 */
export interface IsoMDSResult {
  /** Final low-dimensional coordinates. */
  points: IsoMDSMatrix;
  /** Final Kruskal Stress-1, expressed as a percentage. */
  stress: number;
  /** Initial, periodic and final stress values. */
  trace: IsoMDSTrace[];
}

interface Pair { i: number; j: number; delta: number; group: number; }
interface Evaluation { stress: number; distances: number[]; disparities: number[]; }

function readD(input: DistResult | readonly (readonly number[])[]): { d: number[][]; missing: boolean; labels: string[] | null } {
  if (Array.isArray(input)) {
    const n = input.length;
    if (n < 2 || input.some((r) => r.length !== n)) throw new RangeError("dissimilarity matrix must be square");
    const d = input.map((r) => Array.from(r, Number));
    return { d, missing: d.some((r) => r.some((v) => !Number.isFinite(v))), labels: null };
  }
  if (typeof input !== "object" || input === null || !Array.isArray((input as DistResult).values)) {
    throw new TypeError("d must be a dist object or a square matrix");
  }
  const value = input as DistResult;
  const n = value.size;
  if (!Number.isInteger(n) || n < 2 || value.values.length !== n * (n - 1) / 2) throw new RangeError("invalid dissimilarity object");
  const d = Array.from({ length: n }, () => new Array<number>(n).fill(0));
  let at = 0;
  for (let j = 0; j < n - 1; j++) for (let i = j + 1; i < n; i++) {
    d[i]![j] = value.values[at]!;
    d[j]![i] = value.values[at]!;
    at++;
  }
  return { d, missing: d.some((r) => r.some((v) => !Number.isFinite(v))), labels: value.labels === null ? null : [...value.labels] };
}

function distance(a: readonly number[], b: readonly number[], p: number): number {
  let scale = 0, sum = 1;
  for (let q = 0; q < a.length; q++) {
    const value = Math.abs(a[q]! - b[q]!);
    if (value === 0) continue;
    if (scale < value) { sum = 1 + sum * (scale / value) ** p; scale = value; }
    else sum += (value / scale) ** p;
  }
  return scale === 0 ? 0 : scale * sum ** (1 / p);
}
function center(y: number[][]): void {
  const p = y[0]!.length;
  for (let q = 0; q < p; q++) {
    let m = 0;
    for (const row of y) m += row[q]!;
    m /= y.length;
    for (const row of y) row[q] = row[q]! - m;
  }
}
function pairsFor(d: number[][], missing: boolean): { pairs: Pair[]; groups: number } {
  const n = d.length;
  const pairs: Pair[] = [];
  for (let i = 0; i < n; i++) for (let j = i + 1; j < n; j++) {
    const delta = d[i]![j]!;
    if (!Number.isFinite(delta)) continue;
    if (delta <= 0) throw new RangeError("zero or negative distance between objects");
    pairs.push({ i, j, delta, group: 0 });
  }
  void missing;
  // R's as.vector(dist) visits the lower triangle column by column. Keep that
  // order for equal dissimilarities; the same ordered pairs feed disparities
  // and the gradient, so a different tie order changes the optimization path.
  pairs.sort((a, b) => a.delta - b.delta || a.i - b.i || a.j - b.j);
  let groups = 0;
  for (const pair of pairs) pair.group = groups++;
  return { pairs, groups };
}

/** Pool-adjacent-violators regression in stable lower-triangle pair order. */
function disparitiesFor(pairs: readonly Pair[], groups: number, distances: readonly number[]): number[] {
  // Each pair is an individual observation. Equal dissimilarities retain their
  // lower-triangle order; they are not pooled into a single tie-block mean.
  const starts: number[] = [], ends: number[] = [], values: number[] = [], weights: number[] = [];
  for (let g = 0; g < groups; g++) {
    starts.push(g); ends.push(g); values.push(distances[g]!); weights.push(1);
    while (values.length > 1 && values[values.length - 2]! > values[values.length - 1]!) {
      const last = values.length - 1;
      const w = weights[last - 1]! + weights[last]!;
      values[last - 1] = (values[last - 1]! * weights[last - 1]! + values[last]! * weights[last]!) / w;
      weights[last - 1] = w;
      ends[last - 1] = ends[last]!;
      starts.pop(); ends.pop(); values.pop(); weights.pop();
    }
  }
  const fitted = new Array<number>(groups);
  for (let b = 0; b < values.length; b++) for (let g = starts[b]!; g <= ends[b]!; g++) fitted[g] = values[b]!;
  return pairs.map((pair) => fitted[pair.group]!);
}
function evaluate(y: number[][], pairs: readonly Pair[], groups: number[], p: number): Evaluation {
  const distances = pairs.map((pair) => distance(y[pair.i]!, y[pair.j]!, p));
  const disparities = disparitiesFor(pairs, groups.length, distances);
  let numerator = 0, denominator = 0;
  for (let i = 0; i < distances.length; i++) {
    const d = distances[i]!, diff = d - disparities[i]!;
    numerator += diff * diff;
    denominator += d * d;
  }
  return { stress: denominator === 0 ? 0 : 100 * Math.sqrt(numerator / denominator), distances, disparities };
}
function gradient(y: number[][], pairs: readonly Pair[], current: Evaluation, p: number): number[][] {
  const n = y.length, dim = y[0]!.length;
  const out = Array.from({ length: n }, () => new Array<number>(dim).fill(0));
  let numerator = 0, denominator = 0;
  for (let at = 0; at < current.distances.length; at++) {
    const d = current.distances[at]!;
    const diff = d - current.disparities[at]!;
    numerator += diff * diff;
    denominator += d * d;
  }
  if (numerator === 0 || denominator === 0) return out;
  const ratio = numerator / denominator;
  const common = 100 / (Math.sqrt(ratio) * denominator);
  for (let at = 0; at < pairs.length; at++) {
    const pair = pairs[at]!, d = current.distances[at]!;
    if (d === 0) continue;
    const factor = common * (d - current.disparities[at]! - ratio * d) / (d ** (p - 1));
    for (let q = 0; q < dim; q++) {
      const diff = y[pair.i]![q]! - y[pair.j]![q]!;
      const v = diff === 0 ? 0 : factor * Math.sign(diff) * (Math.abs(diff) ** (p - 1));
      out[pair.i]![q] = out[pair.i]![q]! + v;
      out[pair.j]![q] = out[pair.j]![q]! - v;
    }
  }
  return out;
}
function flatten(y: number[][]): Float64Array {
  const out = new Float64Array(y.length * y[0]!.length);
  let at = 0;
  for (const row of y) for (const value of row) out[at++] = value;
  return out;
}
function unflatten(x: Float64Array, n: number, dim: number): number[][] {
  return Array.from({ length: n }, (_, i) => Array.from({ length: dim }, (_, q) => x[i * dim + q]!));
}
function identity(size: number, diagonal = 1): Float64Array {
  const out = new Float64Array(size * size);
  for (let i = 0; i < size; i++) out[i * size + i] = diagonal;
  return out;
}
function multiply(matrix: Float64Array, vector: Float64Array, size: number): Float64Array {
  const out = new Float64Array(size);
  for (let i = 0; i < size; i++) {
    let value = 0, offset = i * size;
    for (let j = 0; j < size; j++) value += matrix[offset + j]! * vector[j]!;
    out[i] = value;
  }
  return out;
}
/** Full inverse-Hessian BFGS update, with a symmetric rank-two correction. */
function updateInverseHessian(h: Float64Array, step: Float64Array, change: Float64Array, size: number, resetDiagonal: number): Float64Array {
  let curvature = 0;
  for (let i = 0; i < size; i++) curvature += step[i]! * change[i]!;
  if (!(curvature > 0) || !Number.isFinite(curvature)) return identity(size, resetDiagonal);
  const hy = multiply(h, change, size);
  let yhy = 0;
  for (let i = 0; i < size; i++) yhy += change[i]! * hy[i]!;
  const coefficient = (curvature + yhy) / (curvature * curvature);
  const out = new Float64Array(h.length);
  for (let i = 0; i < size; i++) {
    const row = i * size;
    for (let j = 0; j < size; j++) {
      out[row + j] = h[row + j]! + coefficient * step[i]! * step[j]!
        - (hy[i]! * step[j]! + step[i]! * hy[j]!) / curvature;
    }
  }
  return out;
}

function orient(y: number[][]): void {
  const p = y[0]!.length;
  for (let q = 0; q < p; q++) {
    let at = 0, largest = -1;
    for (let i = 0; i < y.length; i++) if (Math.abs(y[i]![q]!) > largest) { largest = Math.abs(y[i]![q]!); at = i; }
    if (y[at]![q]! < 0) for (const row of y) row[q] = -row[q]!;
  }
}

/**
 * Kruskal's non-metric multidimensional scaling.
 * Equivalent to R's `MASS::isoMDS()`.
 * @category Multivariate analysis
 */
export function isoMDS(
  input: DistResult | readonly (readonly number[])[],
  options: IsoMDSOptions = {},
): IsoMDSResult {
  checkOptions(options, ISO_MDS_KEYS, "isoMDS"); // generated: option-keys.mjs
  const parsed = readD(input);
  const n = parsed.d.length;
  const k = options.k ?? 2;
  if (!Number.isInteger(k) || k < 1 || k >= n) throw new RangeError(`'k' must be in {1, 2, ..  ${n - 1}}`);
  const p = options.p ?? 2;
  if (!Number.isFinite(p) || p <= 0) throw new RangeError("'p' must be positive");
  const maxit = options.maxit ?? 50;
  const tol = options.tol ?? 1e-3;
  if (!Number.isInteger(maxit) || maxit < 0) throw new RangeError("'maxit' must be non-negative");
  if (!Number.isFinite(tol) || tol <= 0) throw new RangeError("'tol' must be positive");
  if (parsed.missing && options.y === undefined) throw new RangeError("an initial configuration must be supplied with NA/Infs in 'd'");
  if (Array.isArray(input)) throw new TypeError("d must be a dist object");
  const built = pairsFor(parsed.d, parsed.missing);
  if (options.y !== undefined && (options.y.length !== n || options.y.some((r) => r.length !== k))) {
    throw new RangeError("invalid initial configuration");
  }
  const condensed: number[] = [];
  for (let j = 0; j < n - 1; j++) for (let i = j + 1; i < n; i++) condensed.push(parsed.d[i]![j]!);
  let y = options.y === undefined
    ? cmdscale({ values: condensed, size: n, labels: null, method: null, diag: false, upper: false, warnings: [] }, { k }).points.values
    : options.y.map((r) => Array.from(r));
  if (y.length !== n || y.some((r) => r.length !== k)) throw new RangeError("invalid initial configuration");
  if (y.some((r) => r.some((v) => !Number.isFinite(v)))) throw new RangeError("initial configuration must be finite");
  center(y);
  const groups = Array.from({ length: built.groups }, (_, i) => i);
  let x = flatten(y);
  let current = evaluate(y, built.pairs, groups, p);
  const trace: IsoMDSTrace[] = [{ iteration: 0, stress: current.stress, converged: current.stress === 0 || maxit === 0 }];
  const recordProgress = (iteration: number, stress: number): void => {
    const previous = trace[trace.length - 1];
    // R's printed progress is to six decimals; repeated internal steps that
    // print the same iteration and value are one observable progress record.
    if (previous?.iteration === iteration && previous.stress.toFixed(6) === stress.toFixed(6)) return;
    trace.push({ iteration, stress, converged: false });
  };
  let converged = current.stress === 0 || maxit === 0;
  let lastIter = 0;
  const size = x.length;
  // R starts BFGS from the identity in the original coordinates (choice 13).
  const resetDiagonal = 1;
  let inverseHessian = identity(size, resetDiagonal);
  // R performs one initial BFGS update for maxit=1 and maxit=2; thereafter
  // each additional requested iteration contributes one update.
  const steps = maxit === 0 ? 0 : maxit === 1 ? 1 : maxit - 1;
  let failedSearchWasReset = false;
  // Whether the inverse Hessian is the identity: at the start, after a non-descent direction, a failed line search or
  // an update with a nonpositive curvature. R's extra step at the tol stop happens only when it is not (Claude,
  // 2026-11-24: swiss_y stops at its 4th update without the extra step; swiss at tol 1e-3, 1e-4, 1e-8 takes it)
  let hessianIsIdentity = true;
  for (let stepIndex = 0; stepIndex < steps && !converged; stepIndex++) {
    const iteration = maxit === 1 ? 1 : stepIndex + 2;
    lastIter = iteration;
    // A zero configuration distance leaves the gradient undefined. R then does not move: it returns the start, printing
    // "stopped after 1 iterations" for maxit = 1 and "converged" otherwise, without a warning (swiss_y_k1: the start has
    // two equal values; experiments/isomds111-diverge-more, Claude 2026-11-24)
    if (current.distances.some((v) => v === 0)) { converged = maxit > 1; break; }
    const grad = flatten(gradient(y, built.pairs, current, p));
    let direction = multiply(inverseHessian, grad, size);
    for (let i = 0; i < size; i++) direction[i] = -direction[i]!;
    let directionalDerivative = 0;
    for (let i = 0; i < size; i++) directionalDerivative += grad[i]! * direction[i]!;
    if (!(directionalDerivative < 0) || !Number.isFinite(directionalDerivative)) {
      inverseHessian = identity(size, resetDiagonal);
      hessianIsIdentity = true;
      direction = grad.map((v) => -v);
      directionalDerivative = 0;
      for (let i = 0; i < size; i++) directionalDerivative += grad[i]! * direction[i]!;
    }
    if (!(directionalDerivative < 0)) { converged = true; break; }
    const lineSearch = (searchDirection: Float64Array, slope: number): {
      x: Float64Array; y: number[][]; evaluation: Evaluation;
    } | null => {
      let stepLength = 1;
      for (let trial = 0; trial < 100; trial++) {
        const candidateX = new Float64Array(size);
        let changed = false;
        for (let i = 0; i < size; i++) {
          candidateX[i] = x[i]! + stepLength * searchDirection[i]!;
          if (candidateX[i] !== x[i]) changed = true;
        }
        if (!changed) return null;
        const candidate = unflatten(candidateX, n, k);
        const next = evaluate(candidate, built.pairs, groups, p);
        if (Number.isFinite(next.stress) && next.stress <= current.stress + 1e-4 * stepLength * slope) {
          return { x: candidateX, y: candidate, evaluation: next };
        }
        stepLength *= 0.2;
      }
      return null;
    };
    let accepted = lineSearch(direction, directionalDerivative);
    if (accepted === null) {
      inverseHessian = identity(size, resetDiagonal);
      hessianIsIdentity = true;
      if (failedSearchWasReset) { converged = true; break; }
      failedSearchWasReset = true;
      direction = grad.map((v) => -v);
      directionalDerivative = 0;
      for (let i = 0; i < size; i++) directionalDerivative += grad[i]! * direction[i]!;
      accepted = lineSearch(direction, directionalDerivative);
      if (accepted === null) { converged = true; break; }
    }
    const previousStress = current.stress;
    const nextGradient = flatten(gradient(accepted.y, built.pairs, accepted.evaluation, p));
    const displacement = new Float64Array(size);
    const gradientChange = new Float64Array(size);
    for (let i = 0; i < size; i++) {
      displacement[i] = accepted.x[i]! - x[i]!;
      gradientChange[i] = nextGradient[i]! - grad[i]!;
    }
    const wasIdentity = hessianIsIdentity;
    let curvature = 0;
    for (let i = 0; i < size; i++) curvature += displacement[i]! * gradientChange[i]!;
    hessianIsIdentity = !(curvature > 0) || !Number.isFinite(curvature);
    inverseHessian = updateInverseHessian(inverseHessian, displacement, gradientChange, size, resetDiagonal);
    x = accepted.x;
    y = accepted.y;
    current = accepted.evaluation;
    failedSearchWasReset = false;
    if (iteration % 5 === 0) recordProgress(iteration, current.stress);
    const relativeChange = (previousStress - current.stress) / Math.max(Math.abs(previousStress), Number.MIN_VALUE);
    if (current.stress === 0) {
      converged = true;
    } else if (relativeChange >= 0 && relativeChange < tol) {
      // R's public results show a final extra step after a later (not the first)
      // BFGS update. It uses the previous point's gradient again, from the new
      // configuration, rather than the freshly evaluated gradient or -H*g.
      // On swiss this gives 4.492668758998103 (R: 4.4926687589981045);
      // at tol=1e-8 it gives 4.219287127030445 (R: 4.21928712703045).
      if (!wasIdentity && !hessianIsIdentity) {
        const finalDirection = grad.map((value) => -value);
        let finalSlope = 0;
        for (let i = 0; i < size; i++) finalSlope += grad[i]! * finalDirection[i]!;
        const finalStep = lineSearch(finalDirection, finalSlope);
        if (finalStep !== null) {
          // R prints the extra final step with the preceding iteration number.
          // If the threshold step is just after a five-iteration report, both
          // the threshold point and this final point appear under that number.
          const reportIteration = iteration % 5 === 0 ? iteration : iteration - 1;
          if (iteration % 5 !== 0 && reportIteration % 5 === 0) {
            recordProgress(reportIteration, current.stress);
          }
          x = finalStep.x;
          y = finalStep.y;
          current = finalStep.evaluation;
          if (reportIteration % 5 === 0) {
            recordProgress(reportIteration, current.stress);
          }
          lastIter = reportIteration;
        }
      }
      // R prints no "iter" line for the iteration at which it stops without the extra step (swiss_y at 5)
      if (!(!wasIdentity && !hessianIsIdentity) && iteration % 5 === 0 && trace.at(-1)?.iteration === iteration) trace.pop();
      converged = true;
    }
  }
  if (maxit > 0) trace.push({ iteration: lastIter, stress: current.stress, converged });

  orient(y);
  return { points: { rows: parsed.labels, cols: null,
    values: y.map((r) => [...r]) }, stress: current.stress, trace };
}
